  const [cookieAccepted, setCookieAccepted] = useState<boolean | null>(null)

  useEffect(() => {
    const pref = localStorage.getItem('ws_cookie_consent')
    if (pref) setCookieAccepted(pref === 'accepted')
  }, [])

  const handleCookie = (accepted: boolean) => {
    localStorage.setItem('ws_cookie_consent', accepted ? 'accepted' : 'declined')
    setCookieAccepted(accepted)
  }

  return (
    <div className="grain bg-gradient-mesh min-h-screen">
      <Navbar />
      <main>
        <Hero />
        <FeaturedProduct />
        <UseCases />
        <PlatformDiagram />
        <IndustryTabs />
        <CompanyCulture />
        <RenewablesCTA />
      </main>
      <Footer />
      {cookieAccepted === null && <CookieBanner onAccept={() => handleCookie(true)} onDecline={() => handleCookie(false)} />}
    </div>
  )
}

export default App

import { useState, FormEvent } from 'react'
import Navbar from '../components/Navbar'
import Footer from '../components/Footer'
import { siteConfig } from '../config/site'
import { Send, Globe, Mail, Phone, MapPin } from 'lucide-react'

export default function RequestDemo() {
  const [formData, setFormData] = useState<Record<string, string>>({})
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [submitted, setSubmitted] = useState(false)

  const validate = () => {
    const newErrors: Record<string, string> = {}
    siteConfig.demoForm.fields.forEach((field) => {
      if (field.required && !formData[field.name]?.trim()) {
        newErrors[field.name] = `${field.label} is required`
      }
      if (field.type === 'email' && formData[field.name]) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
        if (!emailRegex.test(formData[field.name])) {
          newErrors[field.name] = 'Please enter a valid email address'
        }
      }
    })
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault()
    if (validate()) {
      setSubmitted(true)
    }
  }

  return (
    <div className="grain bg-gradient-mesh min-h-screen">
      <Navbar />
      <main>
        <section className="relative pt-32 pb-20 lg:pt-48 lg:pb-32 overflow-hidden">
