            <div className="max-w-3xl">
              <h1 className="font-display text-4xl sm:text-5xl lg:text-6xl font-bold text-text-primary leading-[1.05] tracking-tight mb-6">
                {siteConfig.demoForm.heading}
              </h1>
              <p className="text-lg text-text-secondary leading-relaxed max-w-2xl">
                {siteConfig.demoForm.description}
              </p>
            </div>
          </div>
        </section>

        <section className="py-8 pb-20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 lg:grid-cols-5 gap-12">
              {/* Form */}
              <div className="lg:col-span-3">
                {submitted ? (
                  <div className="p-8 rounded-2xl bg-green-400/10 border border-green-400/20 text-center">
                    <div className="w-16 h-16 rounded-full bg-green-400/20 flex items-center justify-center mx-auto mb-4">
                      <Send className="w-8 h-8 text-green-400" />
                    </div>
                    <h3 className="font-display text-2xl font-bold text-text-primary mb-2">Thank You!</h3>
                    <p className="text-text-secondary">
                      Your demo request has been submitted. Our team will contact you shortly to schedule your personalized demonstration.
                    </p>
                  </div>
                ) : (
                  <form onSubmit={handleSubmit} className="p-8 rounded-2xl bg-navy-800/40 border border-white/5">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                      {siteConfig.demoForm.fields.map((field) => (
                        <div key={field.name} className={field.type === 'textarea' ? 'sm:col-span-2' : ''}>
                          <label className="block text-sm font-medium text-text-secondary mb-1.5">
                            {field.label}
                            {field.required && <span className="text-teal-400 ml-1">*</span>}
                          </label>
                          {field.type === 'textarea' ? (
                            <textarea
                              rows={4}
                              value={formData[field.name] || ''}
                              onChange={(e) =>
                                setFormData((prev) => ({ ...prev, [field.name]: e.target.value }))
                              }
                              className={`w-full px-4 py-3 rounded-lg bg-navy-700/60 border text-text-primary placeholder-text-muted text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/50 transition-all resize-none ${
                                errors[field.name] ? 'border-red-400/50' : 'border-white/5'
                              }`}
                              placeholder={`Enter ${field.label.toLowerCase()}`}
                            />
                          ) : (
                            <input
                              type={field.type}
                              value={formData[field.name] || ''}
                              onChange={(e) =>
                                setFormData((prev) => ({ ...prev, [field.name]: e.target.value }))
                              }
                              className={`w-full px-4 py-3 rounded-lg bg-navy-700/60 border text-text-primary placeholder-text-muted text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/50 transition-all ${
                                errors[field.name] ? 'border-red-400/50' : 'border-white/5'
                              }`}
                              placeholder={`Enter ${field.label.toLowerCase()}`}
                            />
                          )}
                          {errors[field.name] && (
                            <p className="mt-1.5 text-xs text-red-400">{errors[field.name]}</p>
                          )}
                        </div>
                      ))}
                    </div>
                    <button
                      type="submit"
                      className="mt-6 w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3.5 rounded-lg bg-teal-500 hover:bg-teal-400 text-navy-950 font-semibold transition-all hover:shadow-lg hover:shadow-teal-500/20"
                    >
                      {siteConfig.demoForm.cta}
                      <Send className="w-4 h-4" />
                    </button>
                  </form>
                )}
              </div>

              {/* Support Contact */}
              <div className="lg:col-span-2">
                <div className="p-8 rounded-2xl bg-navy-800/40 border border-white/5 sticky top-24">
