                      <Phone className="w-5 h-5 text-teal-400 shrink-0 mt-0.5" />
                      <div>
                        <p className="text-sm font-medium text-text-primary">Middle East / North Africa</p>
                        <p className="text-xs text-text-secondary">Dedicated Account Management</p>
                      </div>
                    </div>
                    <div className="pt-5 border-t border-white/5">
                      <div className="flex items-center gap-3">
                        <Mail className="w-5 h-5 text-green-400 shrink-0" />
                        <a href="mailto:support@wellstream.com" className="text-sm text-green-400 hover:text-green-300 transition-colors">
                          support@wellstream.com
                        </a>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </section>
      </main>
      <Footer />
    </div>
  )
}
